/**
 * Generate PR Workflow
 *
 * Creates the GitHub Actions workflow for PR quality checks.
 * Runs: build, lint, type check, tests.
 */

import { renderJobEnvBlock } from '../../npm-auth';

/**
 * Generate the PR quality check workflow YAML content
 */
export function generatePrWorkflow(
  options: { npmAuth?: boolean } = {},
): string {
  const envBlock = renderJobEnvBlock(options.npmAuth ?? false);
  return `# Quality Check workflow - runs on PR open/update
# Generated by tsdevstack infra:init-ci
# Do not edit manually - regenerate with infra:generate-ci

name: Quality Check

on:
  pull_request:
    branches: [main]

jobs:
  check:
    runs-on: ubuntu-latest

${envBlock}    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: '22'
          cache: 'npm'

      - name: Install dependencies
        run: npm ci

      - name: Security audit
        run: npm audit --audit-level=high
        continue-on-error: true

      - name: Build
        run: npm run build

      - name: Lint
        run: npm run lint

      - name: Type check
        run: npm run tsc

      - name: Test
        run: npm run test
`;
}
